#!/usr/bin/env Rscript
suppressPackageStartupMessages({ library(optparse); library(jsonlite); library(ggplot2) })
`%||%` <- function(a,b) if (is.null(a)) b else a
op <- parse_args(OptionParser(option_list=list(make_option('--input',type='character'),make_option('--params',type='character'),make_option('--output',type='character'))))
out <- op$output %||% getwd(); dir.create(out,recursive=TRUE,showWarnings=FALSE)
logmsg <- function(x) cat(sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x),file=file.path(out,'run.log'),append=TRUE)
fail <- function(m,d='',s='Check the input format and params.json.') { write(toJSON(list(error=m,detail=d,suggestion=s),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json')); logmsg(paste(m,d)); quit(status=1) }
tryCatch({
 if(is.null(op$input)||!file.exists(op$input)) fail('Input file not found',as.character(op$input))
 p0 <- if(!is.null(op$params)&&file.exists(op$params)) fromJSON(op$params,simplifyVector=FALSE) else list()
 p <- p0; for(n in names(p0)) if(is.list(p0[[n]])) p <- c(p,p0[[n]])
 get <- function(n,d=NULL,a=character()) { x<-p[[n]]; if(is.null(x)) for(k in a) if(!is.null(p[[k]])){x<-p[[k]];break}; if(is.null(x)) d else x }
 vec <- function(x) if(is.null(x)) character() else trimws(as.character(unlist(x,use.names=FALSE)))
 one <- function(n,d=NULL,a=character()) { x<-unlist(get(n,d,a),use.names=FALSE); if(!length(x)) d else x[1] }
 num <- function(n,d,a=character()) { x<-suppressWarnings(as.numeric(one(n,d,a))); if(is.na(x)) d else x }
 boo <- function(n,d=FALSE,a=character()) { x<-one(n,d,a); if(is.logical(x)) isTRUE(x) else tolower(as.character(x))%in%c('true','t','yes','y','1','on') }
 named <- function(n,d=c()) { x<-unlist(get(n,d),use.names=TRUE); if(length(x)&&is.null(names(x))) names(x)<-character(); x }
 readtab <- function(f) { e<-tolower(tools::file_ext(f)); if(e=='csv') read.csv(f,check.names=FALSE,stringsAsFactors=FALSE) else if(e%in%c('tsv','txt')) read.delim(f,check.names=FALSE,stringsAsFactors=FALSE) else fail('Unsupported input file type',e,'Use CSV, TSV, or TXT.') }
 d<-readtab(op$input); if(ncol(d)<2) fail('Binary matrix needs an id column and at least one matrix column')
 idcol<-as.character(one('row_id_column',names(d)[1])); if(!idcol%in%names(d)) idcol<-names(d)[1]; ids<-as.character(d[[idcol]])
 groupcol<-as.character(one('group_column','')); if(!nzchar(groupcol)||!groupcol%in%names(d)) groupcol<-''
 input_mode<-tolower(as.character(one('input_mode','wide'))); transpose<-boo('transpose',FALSE)
 if(input_mode=='long') {
   rc<-as.character(one('row_column',idcol)); cc<-as.character(one('column_column','column')); vc<-as.character(one('value_column','value')); if(!all(c(rc,cc,vc)%in%names(d))) fail('Long input requires row_column, column_column, and value_column')
   rows<-unique(as.character(d[[rc]])); cols<-unique(as.character(d[[cc]])); mat<-matrix(NA_character_,length(rows),length(cols),dimnames=list(rows,cols)); for(i in seq_len(nrow(d))) mat[as.character(d[[rc]][i]),as.character(d[[cc]][i])]<-as.character(d[[vc]][i])
   groups<-setNames(rep('All',length(rows)),rows)
 } else {
   cols<-setdiff(names(d),c(idcol,groupcol)); ci<-vec(get('column_include',NULL,c('columns_include'))); ce<-vec(get('column_exclude',NULL,c('columns_exclude'))); if(length(ci)) cols<-intersect(cols,ci); cols<-setdiff(cols,ce); if(!length(cols)) fail('No matrix columns remain after filtering')
   mat<-as.matrix(d[,cols,drop=FALSE]); rownames(mat)<-ids; groups<-if(nzchar(groupcol)) setNames(as.character(d[[groupcol]]),ids) else setNames(rep('All',length(ids)),ids)
 }
 truev<-tolower(vec(get('true_values',c('1','true','t','yes','y')))); falsev<-tolower(vec(get('false_values',c('0','false','f','no','n')))); missv<-tolower(vec(get('missing_values',c('','na','nan','null')))); threshold<-num('value_threshold',.5)
 tobin<-function(x) { s<-tolower(trimws(as.character(x))); z<-rep(NA_real_,length(s)); z[s%in%truev]<-1; z[s%in%falsev]<-0; q<-suppressWarnings(as.numeric(s)); z[is.na(z)&is.finite(q)]<-as.numeric(q[is.na(z)&is.finite(q)]>=threshold); z[s%in%missv]<-NA; z }; bmat<-apply(mat,2,tobin); dimnames(bmat)<-dimnames(mat); if(transpose){bmat<-t(bmat); tmp<-groups; groups<-setNames(rep('All',nrow(bmat)),rownames(bmat)); rownames(bmat)<-colnames(mat); colnames(bmat)<-rownames(mat); cols<-colnames(bmat)}
 keep<-rep(TRUE,nrow(bmat)); ri<-vec(get('rows_include')); re<-vec(get('rows_exclude')); if(length(ri)) keep<-rownames(bmat)%in%ri; if(length(re)) keep<-keep&!rownames(bmat)%in%re; bmat<-bmat[keep,,drop=FALSE]; groups<-groups[rownames(bmat)]; if(!nrow(bmat)||!ncol(bmat)) fail('No cells remain after filtering')
 ro<-vec(get('row_order')); co<-vec(get('column_order')); if(length(ro)) rn<-c(intersect(ro,rownames(bmat)),setdiff(rownames(bmat),ro)) else rn<-rownames(bmat); if(length(co)) cn<-c(intersect(co,colnames(bmat)),setdiff(colnames(bmat),co)) else cn<-colnames(bmat)
 if(boo('sort_rows')) rn<-rn[order(rn)]; if(boo('sort_columns')) cn<-cn[order(cn)]; if(boo('reverse_rows')) rn<-rev(rn); if(boo('reverse_columns')) cn<-rev(cn); bmat<-bmat[rn,cn,drop=FALSE]; groups<-groups[rn]
 z<-expand.grid(row=rn,column=cn,stringsAsFactors=FALSE); z$value<-as.vector(bmat); z$binary<-ifelse(is.na(z$value),NA, z$value>0); z$group<-as.character(groups[z$row]); z$group[is.na(z$group)|!nzchar(z$group)]<-'All'; z$highlight<-z$row%in%vec(get('highlight_rows'))|z$column%in%vec(get('highlight_columns')); hc<-vec(get('highlight_cells')); if(length(hc)) z$highlight<-z$highlight|paste(z$row,z$column,sep=':')%in%hc; z$selected<-z$highlight
 logmsg(sprintf('Normalized matrix: %d rows x %d columns',nrow(bmat),ncol(bmat))); write.csv(z[,c('row','column','value','binary','group')],file.path(out,'binary_matrix_used.csv'),row.names=FALSE); if(any(z$highlight)) write.csv(z[z$highlight,c('row','column','value','binary','group')],file.path(out,'selected_cells.csv'),row.names=FALSE)
 z$row<-factor(z$row,levels=rev(rn)); z$column<-factor(z$column,levels=cn); true_shape<-if(as.character(one('true_shape','circle'))%in%c('circle','filled_circle')) 16 else 21; false_shape<-if(as.character(one('false_shape','circle'))%in%c('circle','open_circle')) 1 else 21
 tc<-named('true_colors'); if(!length(tc))tc<-named('row_group_colors'); gr<-unique(z$group); go<-vec(get('group_order')); if(length(go))gr<-c(intersect(go,gr),setdiff(gr,go)); pal<-scales::hue_pal()(length(gr)); names(pal)<-gr; if(length(tc)){for(n in intersect(names(tc),gr))pal[n]<-as.character(tc[n])}; false_color<-as.character(one('false_color','#B8C0CC')); miss_color<-as.character(one('missing_color','#EEEEEE')); z$color<-ifelse(is.na(z$binary),miss_color,ifelse(z$binary,pal[z$group],false_color)); z$size<-ifelse(is.na(z$binary),num('false_size',3),ifelse(z$binary,num('true_size',4),num('false_size',3))); if(boo('size_by_value')) z$size<-scales::rescale(abs(z$value),to=c(num('min_size',2),num('max_size',6)),from=range(abs(z$value),na.rm=TRUE))
 true_shape<-if(as.character(one('true_shape',one('true_symbol','circle')))%in%c('circle','filled_circle'))16 else 21; false_shape<-if(as.character(one('false_shape',one('false_symbol','circle')))%in%c('circle','open_circle'))1 else 21; stroke<-num('stroke',num('border_width',.6)); g<-ggplot(z,aes(column,row)); if(boo('grid_show',TRUE)) g<-g+geom_tile(fill=NA,colour=as.character(one('grid_color','#D9D9D9')),linewidth=num('grid_width',.25)); g<-g+geom_point(data=z[!is.na(z$binary)&!z$binary,],shape=false_shape,colour=false_color,size=z[!is.na(z$binary)&!z$binary,'size'],alpha=num('false_alpha',1),stroke=stroke)+geom_point(data=z[!is.na(z$binary)&z$binary,],aes(colour=group),shape=true_shape,fill=z[!is.na(z$binary)&z$binary,'color'],size=z[!is.na(z$binary)&z$binary,'size'],alpha=num('true_alpha',1),stroke=stroke)+scale_colour_manual(values=pal,name=one('legend_title','Group')) ; if(boo('missing_show',TRUE))g<-g+geom_point(data=z[is.na(z$binary),],shape=21,colour=miss_color,fill=miss_color,size=num('false_size',3))
 if(any(z$highlight))g<-g+geom_point(data=z[z$highlight,],shape=21,colour=as.character(one('highlight_color','#E69F00')),fill=NA,size=num('highlight_size',6),stroke=num('highlight_size',1),alpha=num('highlight_alpha',1)); if(boo('cell_label_show'))g<-g+geom_text(aes(label=ifelse(is.na(value),'',ifelse(boo('cell_label_format','')=='binary',ifelse(binary,'1','0'),as.character(value)))),size=num('cell_label_size',2.5),colour=as.character(one('cell_label_color','#222222')))
 rowcols<-named('row_group_colors'); g<-g+scale_x_discrete(expand=expansion(mult=num('x_expand',.02)))+scale_y_discrete(expand=expansion(mult=num('y_expand',.02)))+labs(x=one('xlab',''),y=one('ylab',''),title=if(boo('title_show',TRUE))one('title','Binary Presence/Absence')else NULL,subtitle=one('subtitle',NULL),caption=one('caption',NULL))+theme_minimal(base_size=num('base_size',11),base_family=one('font_family','sans'))+theme(panel.background=element_rect(fill=one('panel_background','white'),colour=NA),plot.background=element_rect(fill=one('plot_background','white'),colour=NA),panel.grid=element_blank(),axis.text.x=element_text(angle=num('x_text_angle',45),hjust=1,size=num('x_text_size',9),colour=one('x_text_color','#222222')),axis.text.y=element_text(angle=num('y_text_angle',0),size=num('y_text_size',9),colour=one('y_text_color','#222222')),axis.title=element_text(colour=one('axis_line_color','#222222')),plot.title=element_text(size=num('title_size',16),colour=one('title_color','#222222'),face=one('title_face','bold'),hjust=num('title_hjust',.5)),legend.position=if(boo('legend_show',TRUE))one('legend_position','right')else'none',legend.text=element_text(size=num('legend_text_size',9)),legend.title=element_text(size=num('legend_title_size',10)),plot.margin=grid::unit(rep(num('margin',.5),4),'cm')); if(boo('panel_border_show'))g<-g+theme(panel.border=element_rect(colour=one('panel_border_color','#444444'),fill=NA,linewidth=num('panel_border_width',.5)))
 w<-num('width',max(7,min(16,ncol(bmat)*.35))); h<-num('height',max(5,min(14,nrow(bmat)*.35))); dpi<-num('dpi',300); ggsave(file.path(out,'result.svg'),g,width=w,height=h,units='in'); ggsave(file.path(out,'result.pdf'),g,width=w,height=h,units='in'); ggsave(file.path(out,'result.png'),g,width=w,height=h,units='in',dpi=dpi)
 if(boo('interactive',TRUE)&&requireNamespace('plotly',quietly=TRUE)&&requireNamespace('htmlwidgets',quietly=TRUE)){ z$hover<-sprintf('Row: %s<br>Column: %s<br>Value: %s<br>Group: %s',z$row,z$column,ifelse(is.na(z$value),'missing',as.character(z$value)),z$group); pl<-plotly::plot_ly(); for(grp in gr){for(state in c(FALSE,TRUE)){a<-z[z$group==grp&z$binary==state,,drop=FALSE]; if(nrow(a)){st<-if(state) 'true' else 'false'; sy<-if(state) 'circle' else 'circle-open'; co<-if(state) pal[grp] else false_color; sz<-if(state) num('true_size',12) else num('false_size',9); pl<-plotly::add_trace(pl,x=as.character(a$column),y=as.character(a$row),type='scatter',mode='markers',name=paste(grp,st),marker=list(symbol=sy,color=co,size=sz),text=a$hover,hoverinfo='text',customdata=paste(a$row,a$column,sep=':'))}}}; pl<-plotly::layout(pl,title=one('title','Binary Presence/Absence'),xaxis=list(title=one('xlab',''),tickangle=num('x_text_angle',45)),yaxis=list(title=one('ylab',''),autorange='reversed'),showlegend=boo('legend_show',TRUE)); pl<-plotly::config(pl,displaylogo=FALSE,scrollZoom=boo('zoom',TRUE),modeBarButtonsToAdd=if(boo('selectable',TRUE)||boo('lasso_select',TRUE))c('lasso2d','select2d') else character()); htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE) } else writeLines('<html><body><p>Interactive rendering requires the R packages plotly and htmlwidgets.</p></body></html>',file.path(out,'result.html'))
 fig<-list(plugin='interactive_binary_plot',source_engine='ggplot2/plotly',input_mode=input_mode,rows=rn,columns=cn,groups=gr,n_cells=nrow(z),outputs=c('result.svg','result.pdf','result.png','result.html','figure.json','binary_matrix_used.csv')); write(toJSON(fig,auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json')); if(file.exists(file.path(out,'error.json')))unlink(file.path(out,'error.json')); logmsg(sprintf('Rendered %d cells (%d rows x %d columns)',nrow(z),length(rn),length(cn)))
 },error=function(e) fail('Binary plot rendering failed',paste(conditionMessage(e),paste(capture.output(sys.calls()),collapse=' ')),'Check that values are binary/numeric and parameter names are valid.'))
